/**
 * Serves the published app page and its files, and nothing else.
 *
 * The bundle next to this file is generated by ../publish_renders.py from the frames
 * git already has, so there is one copy of every pixel in the repo. This worker only
 * hands static files out; it has no route, no state and no secret.
 */
export default {
  async fetch(request, env) {
    const response = await env.ASSETS.fetch(request);
    if (response.status === 404) {
      return new Response("not here: this origin serves the app's renders only\n", {
        status: 404,
        headers: { "content-type": "text/plain; charset=utf-8" },
      });
    }
    return response;
  },
};
